/**
 * @file optimizer_evaluate.c
 * Project: IFJ26
 *
 * @author Jan Kostka (xkostkj00)
 * @date 25. 11. 2026
 *
 * @brief Bounded constant evaluation of integer, Boolean, and Unit user calls.
 *
 * @details Each invocation tracks its own initialized slots and SSA values.
 * Recursion and loops share a step budget, and only completed calls enter the
 * cache. An unsupported instruction abandons evaluation and leaves the original
 * call in place.
 */

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement"
// Changes: Evaluate bounded integer and Boolean calls without executing
// host-side effects.
#include "optimizer_fold_internal.h"

#include <stdint.h>
#include <string.h>
#include "ir_helpers.h"

enum {
  EVAL_VALUES = 256,
  EVAL_SLOTS = 64,
  EVAL_ARGS = 8,
  EVAL_DEPTH = 32,
  EVAL_CACHE = 128,
  EVAL_STEPS = 20000
};

/**
 * @brief Literal argument tuple and completed result for one evaluated call.
 */
typedef struct {
  IrFunctionId function;
  IrOperand arguments[EVAL_ARGS];
  IrOperand result;
} CachedCall;

/**
 * @brief Shared program, step budget, and memo table for one evaluation
 * attempt.
 */
typedef struct {
  const IrProgram* program;
  unsigned remaining;
  size_t count;
  CachedCall cache[EVAL_CACHE];
} Evaluator;

/**
 * @brief Check whether a literal fits the evaluator's supported type and
 * integer domain.
 *
 * @param operand Literal to check.
 * @return True if the evaluator can represent the literal.
 */
static bool supported(IrOperand operand) {
  return operand.type == IR_OP_BOOL || operand.type == IR_OP_UNIT ||
         (operand.type == IR_OP_INT32 &&
          operand.value.int32_value >= INT32_MIN &&
          operand.value.int32_value <= INT32_MAX);
}

/**
 * @brief Compare two evaluator literals for equality, including Unit.
 *
 * @param a First supported literal.
 * @param b Second supported literal.
 * @return True if the literals have equal types and values.
 */
static bool equal(IrOperand a, IrOperand b) {
  if (a.type != b.type)
    return false;

  if (a.type == IR_OP_BOOL)
    return a.value.bool_value == b.value.bool_value;

  if (a.type == IR_OP_INT32)
    return a.value.int32_value == b.value.int32_value;

  return a.type == IR_OP_UNIT;
}

/**
 * @brief Resolve a literal or initialized SSA value from the evaluation frame.
 *
 * @param source Operand to resolve.
 * @param values SSA values indexed by ID.
 * @param initialized Flags for values defined on the current path.
 * @param[out] result Resolved literal.
 * @return True if a supported literal was available.
 */
static bool lookup(IrOperand source,
                   const IrOperand* values,
                   const bool* initialized,
                   IrOperand* result) {
  if (source.type == IR_OP_VALUE) {
    size_t id = source.value.id;
    if (id >= EVAL_VALUES || !initialized[id])
      return false;
    source = values[id];
  }

  if (!supported(source))
    return false;
  *result = source;
  return true;
}

/**
 * @brief Store a Boolean result and report successful evaluation.
 *
 * @param[out] out Operand receiving the comparison result.
 * @param comparison Boolean result.
 * @return True to report successful evaluation.
 */
// Comparisons produce a Boolean directly; only arithmetic needs a range check.
static bool set_predicate(IrOperand* out, bool comparison) {
  *out = (IrOperand){IR_OP_BOOL, {.bool_value = comparison}};
  return true;
}

/**
 * @brief Evaluate a binary operation in the supported domain and reject faults
 * or overflow.
 *
 * @param kind IR operation to evaluate.
 * @param a Left literal operand.
 * @param b Right literal operand.
 * @param[out] out Evaluated result.
 * @return True if the operation is supported and its result is in range.
 */
static bool binary(IrInstructionType kind,
                   IrOperand a,
                   IrOperand b,
                   IrOperand* out) {
  if (kind == IR_INST_EQ || kind == IR_INST_NE) {
    if (a.type != b.type)
      return false;
    *out = (IrOperand){IR_OP_BOOL,
                       {.bool_value = equal(a, b) == (kind == IR_INST_EQ)}};
    return true;
  }

  if (a.type != IR_OP_INT32 || b.type != IR_OP_INT32)
    return false;

  // Inputs are restricted to Int32, so the wider IrInt can hold an
  // intermediate product before the result is checked against that range.
  IrInt x = a.value.int32_value, y = b.value.int32_value, result;
  switch (kind) {
    case IR_INST_ADD:
      result = x + y;
      break;
    case IR_INST_SUB:
      result = x - y;
      break;
    case IR_INST_MUL:
      result = x * y;
      break;
    case IR_INST_IDIV:
      if (!y)
        return false;
      result = x / y;
      break;
    case IR_INST_LT:
      return set_predicate(out, x < y);
    case IR_INST_LE:
      return set_predicate(out, x <= y);
    case IR_INST_GT:
      return set_predicate(out, x > y);
    case IR_INST_GE:
      return set_predicate(out, x >= y);
    default:
      return false;
  }
  *out = (IrOperand){IR_OP_INT32, {.int32_value = result}};
  return supported(*out);
}

/**
 * @brief Interpret one eligible function with a local frame and a shared
 * recursion and step budget.
 *
 * @param eval Shared evaluator state.
 * @param fid Function to evaluate.
 * @param args Literal arguments in parameter order.
 * @param depth Current recursion depth.
 * @param[out] result Constant returned by the evaluated path.
 * @return True if the evaluation reached a supported return.
 */
static bool evaluate(Evaluator* eval,
                     IrFunctionId fid,
                     const IrOperand* args,
                     unsigned depth,
                     IrOperand* result) {
  if (depth == EVAL_DEPTH || !eval->remaining ||
      fid >= eval->program->functions.count)
    return false;

  const IrFunction* fn = &eval->program->functions.data[fid];
  if (fn->slots.count > EVAL_SLOTS || fn->value_count > EVAL_VALUES ||
      fn->parameter_count > EVAL_ARGS ||
      (fn->return_type != IR_INT && fn->return_type != IR_BOOL &&
       fn->return_type != IR_UNIT))
    return false;

  // Memoize completed calls by function and argument tuple, leaving recursion
  // subject to the shared budget.
  for (size_t k = 0; k < eval->count; k++) {
    const CachedCall* cache = &eval->cache[k];

    if (cache->function != fid)
      continue;

    size_t a = 0;
    while (a < fn->parameter_count && equal(args[a], cache->arguments[a]))
      a++;

    if (a == fn->parameter_count) {
      *result = cache->result;
      return true;
    }
  }

  // Track initialization separately because not every SSA value or slot is
  // defined on the path being evaluated.
  IrOperand slots[EVAL_SLOTS], values[EVAL_VALUES];
  bool slot_defined[EVAL_SLOTS] = {false}, value_defined[EVAL_VALUES] = {false};
  for (size_t a = 0; a < fn->parameter_count; a++) {
    slots[a] = args[a];
    slot_defined[a] = true;
  }

  IrBlockId bid = fn->entrypoint;
  while (eval->remaining && bid < fn->blocks.count) {
    eval->remaining--;
    const IrBlock* block = &fn->blocks.data[bid];

    for (size_t i = 0; i < block->instructions.count; i++) {
      if (!eval->remaining)
        return false;

      eval->remaining--;
      IrInstruction inst = block->instructions.data[i];
      IrOperand out = {.type = IR_OP_UNIT};

      // Interpret only explicitly supported operations. A call shares the
      // budget but starts with a fresh frame.
      if (inst.type == IR_INST_LOAD) {
        IrStackSlotId slot = inst.operands.load.source;

        if (slot >= fn->slots.count || !slot_defined[slot])
          return false;

        out = slots[slot];
      } else if (inst.type == IR_INST_STORE) {
        IrStackSlotId slot = inst.operands.store.target;

        if (slot >= fn->slots.count ||
            !lookup(inst.operands.store.source, values, value_defined,
                    &slots[slot]))
          return false;

        slot_defined[slot] = true;
      } else if (inst.type == IR_INST_CALL) {
        IrOperand nested[EVAL_ARGS];
        size_t count = inst.operands.call.arg_count;

        if (count > EVAL_ARGS ||
            inst.operands.call.id >= eval->program->functions.count ||
            eval->program->functions.data[inst.operands.call.id]
                    .parameter_count != count)
          return false;

        for (size_t a = 0; a < count; a++)
          if (!lookup(inst.operands.call.args[a], values, value_defined,
                      &nested[a]))
            return false;

        if (!evaluate(eval, inst.operands.call.id, nested, depth + 1, &out))
          return false;
      } else if (inst.type == IR_INST_NOT) {
        if (!lookup(inst.operands.unary.operand, values, value_defined, &out) ||
            out.type != IR_OP_BOOL)
          return false;

        out.value.bool_value = !out.value.bool_value;
      } else if (ir_get_instruction_class(&inst) == IR_INST_CLASS_BINARY) {
        IrOperand left, right;
        if (!lookup(inst.operands.binary.left, values, value_defined, &left) ||
            !lookup(inst.operands.binary.right, values, value_defined,
                    &right) ||
            !binary(inst.type, left, right, &out))
          return false;
      } else {
        return false;
      }

      if (inst.result != IR_INVALID_ID) {
        if (inst.result >= fn->value_count)
          return false;

        values[inst.result] = out;
        value_defined[inst.result] = true;
      }
    }

    // Follow only the selected CFG edge so a fault on an untaken path cannot
    // block a valid fold.
    const IrBlockTerminator* term = &block->terminator;
    switch (term->type) {
      case IR_TERMINATOR_JUMP:
        bid = term->value.jump_target;
        break;

      case IR_TERMINATOR_CONDITIONAL: {
        IrOperand condition;
        if (!lookup(term->value.conditional_target.condition, values,
                    value_defined, &condition) ||
            condition.type != IR_OP_BOOL)
          return false;
        bid = condition.value.bool_value
                  ? term->value.conditional_target.true_target
                  : term->value.conditional_target.false_target;
        break;
      }

      case IR_TERMINATOR_RETURN:
        if (fn->return_type == IR_UNIT)
          *result = (IrOperand){.type = IR_OP_UNIT};
        else if (!lookup(term->value.return_value, values, value_defined,
                         result) ||
                 result->type !=
                     (fn->return_type == IR_INT ? IR_OP_INT32 : IR_OP_BOOL))
          return false;

        if (eval->count < EVAL_CACHE) {
          CachedCall* cache = &eval->cache[eval->count++];
          cache->function = fid;
          cache->result = *result;

          if (fn->parameter_count)
            memcpy(cache->arguments, args, fn->parameter_count * sizeof(*args));
        }

        return true;

      default:
        return false;
    }
  }

  return false;
}

bool optimizer_evaluate_call(const IrProgram* program,
                             const IrInstruction* call,
                             IrOperand* result) {
  size_t count = call->operands.call.arg_count;
  if (count > EVAL_ARGS || call->operands.call.id >= program->functions.count ||
      program->functions.data[call->operands.call.id].parameter_count != count)
    return false;

  for (size_t i = 0; i < count; i++)
    if (!supported(call->operands.call.args[i]))
      return false;

  Evaluator eval = {.program = program, .remaining = EVAL_STEPS};
  return evaluate(&eval, call->operands.call.id, call->operands.call.args, 0,
                  result);
}
